mapper.select:
SELECT f.*, p.name as patient_name, p.phone as patient_phone FROM follow_up_plan f LEFT JOIN patient p ON f.patient_id = p.id
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND f.status = #{status}
ORDER BY CASE f.status WHEN 'PENDING' THEN 0 WHEN 'MISSED' THEN 1 WHEN 'COMPLETED' THEN 2 ELSE 3 END, CASE WHEN f.status = 'PENDING' AND f.plan_date <= CURDATE() THEN 0 ELSE 1 END, f.plan_date ASC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM follow_up_plan f LEFT JOIN patient p ON f.patient_id = p.id
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND f.status = #{status}
